"""Generates the sample corpus: 50 general CS docs + 5 niche research docs.

Usage:
    python scripts/make_sample_data.py
"""

from __future__ import annotations

from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent

GENERAL_DOCS = {
    "sorting-algorithms": "Sorting algorithms arrange data in order. Bubble sort repeatedly swaps adjacent out-of-order elements and runs in O(n^2). Merge sort divides the array in half, sorts each half, and merges them in O(n log n). Quick sort picks a pivot and partitions elements around it, with O(n log n) average performance. Choosing a sorting algorithm depends on data size, whether the data is nearly sorted, and memory limits.",
    "binary-search": "Binary search finds a target in a sorted array by repeatedly checking the middle element. If the target is smaller, search the left half; otherwise search the right half. Each step halves the search space, giving O(log n) time. The array must be sorted beforehand, and the classic implementation must carefully handle the mid index to avoid infinite loops.",
    "linked-lists": "A linked list stores values in nodes, each holding a value and a pointer to the next node. Inserting or deleting at the head is O(1), but accessing the nth element takes O(n) because there is no random access. Linked lists avoid shifting elements like arrays do, but they use extra memory for pointers and suffer poor cache locality.",
    "stacks-and-queues": "A stack is last-in-first-out: push adds to the top, pop removes from the top. A queue is first-in-first-out: enqueue adds to the back, dequeue removes from the front. Stacks implement function calls, undo history, and expression parsing. Queues handle print jobs and task scheduling. Both can be built on arrays or linked lists.",
    "binary-trees": "A binary tree is a hierarchical structure where each node has at most two children, left and right. In a binary search tree, every left descendant is smaller and every right descendant is larger, which keeps search operations at O(log n) when the tree is balanced. If inserts arrive in sorted order the tree degenerates into a linked list, so self-balancing variants like AVL trees exist.",
    "graph-representation": "Graphs can be stored as an adjacency matrix, a 2D array where cell (i, j) marks an edge, using O(V^2) space, or as an adjacency list mapping each vertex to its neighbors, using O(V + E) space. Sparse graphs favor adjacency lists; dense graphs with many edges favor matrices. Directed graphs store one-way edges, while undirected graphs store both directions.",
    "breadth-first-search": "Breadth-first search explores a graph level by level using a queue. It starts at a source node, visits all neighbors, then the neighbors of those neighbors. BFS finds the shortest path in an unweighted graph and is used for web crawling, social network degrees of separation, and puzzle solving. Its time complexity is O(V + E).",
    "depth-first-search": "Depth-first search explores as far as possible along one branch before backtracking, using a stack or recursion. It is used for cycle detection, topological sorting, and maze solving. DFS has O(V + E) time complexity. Compared to BFS, it uses less memory on deep graphs but does not guarantee the shortest path in unweighted graphs.",
    "dijkstra-algorithm": "Dijkstra's algorithm finds the shortest path from one node to all others in a graph with non-negative edge weights. It greedily visits the unvisited node with the smallest known distance, updating its neighbors. Using a binary heap priority queue it runs in O((V + E) log V). It fails with negative edge weights, where the Bellman-Ford algorithm is used instead.",
    "dynamic-programming": "Dynamic programming solves problems by breaking them into overlapping subproblems and storing their answers so they are computed only once. It works when a problem has optimal substructure, like the knapsack problem or edit distance. The two main techniques are bottom-up tabulation filling a table iteratively and top-down memoization with recursion.",
    "greedy-algorithms": "A greedy algorithm makes the locally optimal choice at each step, hoping to reach a global optimum. It works for problems like activity selection, Huffman coding, and minimum spanning trees with Kruskal's or Prim's algorithm. Greedy methods are fast and simple, but they do not always produce the optimal answer, so correctness must be proven for each problem.",
    "big-o-notation": "Big-O notation describes how an algorithm's running time or memory use grows with input size, ignoring constants and lower-order terms. O(1) is constant time, O(log n) is logarithmic, O(n) is linear, O(n log n) is linearithmic, O(n^2) is quadratic, and O(2^n) is exponential. Choosing an algorithm with better big-O performance matters more than micro-optimizations as data grows.",
    "hash-tables": "A hash table maps keys to values using a hash function that converts a key into an array index. Average lookup, insert, and delete are O(1). Collisions happen when two keys hash to the same index and are resolved with chaining using linked lists or open addressing using probe sequences. A good hash function distributes keys evenly to avoid long chains.",
    "heaps": "A heap is a complete binary tree where every parent is smaller than its children in a min-heap or larger in a max-heap. The root is always the minimum or maximum element. Heaps back priority queues and power heaps in heapsort. Insert and extract-min take O(log n), while peeking at the root is O(1). Arrays represent heaps efficiently using index arithmetic.",
    "recursion": "Recursion is when a function calls itself to solve a smaller instance of the same problem, until it reaches a base case that returns directly. Examples include tree traversal and the Fibonacci sequence. Every recursive call adds a frame to the call stack, so deep recursion can cause a stack overflow. Tail-call optimization can fix this when supported.",
    "arrays": "An array stores elements in contiguous memory, allowing O(1) access to any index by computing an address offset. Inserting or deleting in the middle costs O(n) because later elements must shift. Dynamic arrays like Python lists resize by doubling capacity when full, giving amortized O(1) append. Contiguous storage makes arrays cache-friendly compared to linked lists.",
    "pointers-and-memory": "A pointer is a variable that holds the memory address of another value. Pointers enable dynamic data structures and passing large objects without copying. Dangling pointers reference freed memory, null pointers reference nothing, and memory leaks happen when allocated memory is never freed. In memory-safe languages like Python and Java, pointers are largely hidden from the programmer.",
    "garbage-collection": "Garbage collection automatically reclaims memory that is no longer reachable, preventing manual memory errors. Reference counting frees objects when no references remain but cannot handle cycles. Tracing collectors like mark-and-sweep start from root objects and mark everything reachable, then sweep the rest. Generational collectors assume most objects die young and collect young objects more frequently.",
    "sql-basics": "SQL is the standard language for relational databases. SELECT retrieves rows, WHERE filters them, JOIN combines tables on related columns, and GROUP BY aggregates with functions like COUNT and AVG. Queries are declarative: you describe the result you want, and the database engine decides how to execute it using its query planner.",
    "database-normalization": "Normalization organizes tables to reduce redundancy and prevent update anomalies. First normal form requires atomic values, second normal form removes partial dependencies on part of a composite key, and third normal form removes transitive dependencies where non-key columns depend on each other. Over-normalizing can hurt read performance, so denormalization is sometimes used for reporting workloads.",
    "database-indexes": "An index is an auxiliary data structure, usually a B-tree, that lets the database find rows without scanning the whole table. Queries filtered by indexed columns become much faster, but every index slows down inserts, updates, and deletes because it must be maintained. Composite indexes only help when the leading columns are used in the query.",
    "transactions-and-acid": "A transaction groups operations so they either all succeed or all roll back. ACID guarantees Atomicity all-or-nothing, Consistency moving from one valid state to another, Isolation concurrent transactions do not interfere, and Durability committed data survives crashes. Isolation levels trade correctness for performance, with read committed, repeatable read, and serializable offering increasing strictness.",
    "rest-apis": "REST is an architectural style for web APIs using HTTP methods as verbs: GET reads, POST creates, PUT replaces, PATCH updates, and DELETE removes. Resources are identified by URLs, and stateless requests carry all context, often as JSON in the body. Good REST APIs use consistent naming, proper status codes, and support pagination for large collections.",
    "http-protocol": "HTTP is the request-response protocol of the web. A request has a method, headers, and optionally a body; a response has a status code, headers, and body. Common status codes are 200 OK, 404 Not Found, and 500 Server Error. HTTP/1.1 introduced persistent connections, HTTP/2 multiplexed streams over one connection, and HTTP/3 runs on QUIC over UDP.",
    "tcp-vs-udp": "TCP is a reliable, connection-oriented protocol that orders packets, detects loss, and retransmits, making it suitable for web pages and file transfers. UDP is connectionless and fire-and-forget with no ordering guarantees, but it has lower latency, which suits video streaming, gaming, and DNS lookups. TCP achieves reliability through acknowledgements and sequence numbers.",
    "dns": "The Domain Name System translates human-readable domain names like example.com into IP addresses. Queries are answered by a hierarchy of servers: local resolver, root servers, top-level domain servers, and authoritative name servers. Records include A for IPv4, AAAA for IPv6, and CNAME for aliases. DNS is usually cached, which speeds lookups but delays propagation of changes.",
    "tls-encryption": "Transport Layer Security encrypts traffic between a client and server so eavesdroppers cannot read it. A handshake agrees on cipher suites, the server proves its identity with a certificate signed by a trusted certificate authority, and both sides derive shared session keys. TLS protects confidentiality and integrity, and its padlock icon signals an HTTPS connection.",
    "public-key-cryptography": "Public-key cryptography uses a key pair: a public key shared with everyone and a private key kept secret. RSA and elliptic curve algorithms make encryption with the public key possible only the private key can decrypt, while signatures work the reverse way. It solves the key distribution problem of symmetric encryption, though it is slower, so hybrid systems use it to exchange a symmetric session key.",
    "password-hashing": "Passwords should never be stored in plain text. A password is run through a slow, salted hash function like bcrypt, scrypt, or Argon2 so that stolen databases are hard to crack. Salts are random values unique per user that prevent rainbow table attacks. Adding work factors slows down guessing, and hashing is one-way unlike encryption which can be reversed with the key.",
    "authentication-vs-authorization": "Authentication verifies who you are, for example with a password or a fingerprint. Authorization decides what you are allowed to do, typically with roles and permissions checked after login. A common flow is session tokens or JSON Web Tokens issued at login and attached to later requests. Confusing the two leads to security bugs where authenticated users access other users' data.",
    "processes-and-threads": "A process is an independent program in execution with its own memory space, while threads are lightweight units inside a process that share its memory. Context switching between processes is more expensive than between threads. Threads speed up parallel work but introduce race conditions, so synchronization with locks or queues is required when they share state.",
    "deadlocks": "Deadlock occurs when processes hold resources each other waits for, so none can proceed. The four Coffman conditions are mutual exclusion, hold and wait, no preemption, and circular wait. Prevention breaks one condition, avoidance uses algorithms like Banker's algorithm, and recovery kills or rolls back processes. Thread ordering is a practical way to avoid deadlocks in application code.",
    "virtual-memory": "Virtual memory gives each process its own address space, mapping virtual addresses to physical RAM through page tables. Pages that are not in memory trigger page faults, and the OS swaps them in from disk. This lets programs run with less RAM than their address space requires and isolates processes from each other.",
    "file-systems": "File systems organize storage into files, directories, and metadata. Inodes or file table entries store attributes like size and permissions, while blocks hold the actual data. FAT, ext4, NTFS, and APFS differ in journaling, crash recovery, and support for features like snapshots. Journaling file systems log changes before applying them so crashes do not corrupt the structure.",
    "compilers": "A compiler translates source code into machine code in phases: lexical analysis breaks text into tokens, parsing builds a syntax tree, semantic analysis checks types and scope, optimization improves the intermediate code, and code generation emits instructions. Interpreters execute statements directly. Just-in-time compilers, like the Java Virtual Machine's, compile hot code at runtime for a balance of portability and speed.",
    "regular-expressions": "Regular expressions are a compact notation for matching patterns in text, built from literals, character classes like [0-9], quantifiers like * and +, and anchors like ^ and $. They power search, validation, and text cleanup. Finite automata implement them under the hood, so matching is linear in the input length. Nested quantifiers can cause catastrophic backtracking.",
    "unit-testing": "Unit tests verify small pieces of code in isolation. A good test is fast, deterministic, and independent of other tests, following the arrange-act-assert pattern. Failing tests should pinpoint the broken behavior. Test doubles like stubs and mocks replace slow dependencies such as databases or networks. High coverage catches regressions, but coverage alone does not prove correctness.",
    "version-control-git": "Git tracks changes to source code in a repository. Commits record snapshots, branches line of development, and merges combine them. The three areas are working directory, staging area, and repository. Distributed cloning gives everyone full history, enabling offline work. Git makes experimentation safe because any change can be reverted or compared with git diff.",
    "agile-development": "Agile is an iterative approach where work is delivered in short sprints, typically one to four weeks. The team plans a small batch, builds it, demos it, and retrospects to improve. User stories describe features from the customer's perspective. Agile favors responding to change over following a fixed plan, supported by daily standups and continuous feedback.",
    "cloud-computing": "Cloud computing delivers servers, storage, and services over the internet on demand. The main models are IaaS providing virtual machines, PaaS abstracting the runtime, and SaaS delivering complete applications. Public clouds like AWS, Azure, and Google Cloud offer pay-as-you-go pricing, elasticity to scale with demand, and global regions for low latency.",
    "microservices": "Microservices split an application into small independent services, each owning its own data and deploying separately. Services communicate over HTTP APIs or message queues. The style lets teams scale and release components independently, but it introduces network failures, distributed tracing, and data consistency challenges that a monolith does not have.",
    "caching-strategies": "Caching stores frequently used results closer to the consumer to reduce latency and load. Common policies are least recently used, first in first out, and time to live expiration. Caches appear at many levels: browser, CDN, application memory, and database query cache. The main risk is staleness, so invalidation strategies must be designed deliberately.",
    "load-balancing": "A load balancer distributes incoming requests across multiple servers to avoid overload and improve availability. Algorithms include round robin, least connections, and IP hashing. Load balancers run at layer 4 forwarding packets or layer 7 understanding HTTP, and they perform health checks to remove failing servers from rotation.",
    "message-queues": "Message queues decouple services by letting a producer push work and a consumer process it asynchronously. This smooths traffic spikes, improves resilience when a consumer is down, and enables fan-out patterns with topics. Systems like RabbitMQ and Kafka also support ordering guarantees and retries, at the cost of added operational complexity.",
    "ci-cd-pipelines": "Continuous integration automatically builds and tests code on every commit, catching breakages early. Continuous delivery extends this with automated staging deployments, and continuous deployment releases every passing change to users. A typical pipeline lints, runs tests, builds an artifact, and deploys, with rollback plans for failures. Pipelines are defined as code in YAML files.",
    "containers-docker": "A container packages an application with its dependencies into an isolated, lightweight unit that runs the same on any host. Docker images are built in layers and shared through registries, and containers start in seconds compared to virtual machines. Containers share the host kernel, so they are smaller than VMs but offer less isolation.",
    "os-scheduling": "The OS scheduler decides which process runs on the CPU. Short-term scheduling chooses among ready processes using algorithms like round robin, first-come first-served, and shortest job first. Preemptive scheduling interrupts running processes to share CPU fairly, while non-preemptive scheduling runs to completion. The goal is high throughput, low response time, and fairness.",
    "networking-osi-model": "The OSI model describes networking in seven layers: physical, data link, network, transport, session, presentation, and application. Each layer adds its own header, like envelopes inside envelopes. The practical TCP/IP model collapses this into link, internet, transport, and application layers. Layering lets protocols be replaced independently, such as running IP over Wi-Fi or fiber.",
    "machine-learning-basics": "Machine learning trains models on data instead of explicit rules. Supervised learning fits labeled examples for classification and regression, unsupervised learning finds structure like clusters without labels, and reinforcement learning learns actions from rewards. Training minimizes a loss function through gradient descent, while overfitting is countered with regularization, more data, or held-out validation sets.",
    "neural-networks": "A neural network layers matrices of weights with nonlinear activation functions like ReLU. Backpropagation computes gradients of the loss with respect to each weight, and an optimizer like Adam updates them. Deep networks with many layers learn hierarchical features, enabling image recognition and language models. Training needs large datasets and significant compute, often GPUs.",
}

RESEARCH_DOCS = {
    "byzantine-fault-tolerance": "Byzantine fault tolerance allows a distributed system to reach agreement even when some nodes behave arbitrarily, crashing, lying, or colliding. The PBFT protocol tolerates up to f faulty replicas among 3f+1 total by exchanging pre-prepare, prepare, and commit messages in three phases. The classic result is that consensus requires 3f+1 nodes to survive f Byzantine faults. PBFT is used in permissioned blockchains and mission-critical replication where silent data corruption must not break correctness.",
    "crdts-conflict-free-replication": "Conflict-free replicated data types are data structures designed so that replicas can be updated independently and merged without coordination while always converging. Grow-only sets, last-writer-wins registers, and counters that only increment are examples. Merge operations are commutative, associative, and idempotent, typically built on join semilattices. CRDTs power offline-first apps and collaborative editors, trading strong consistency for availability under partition, as formalized by the CAP theorem.",
    "differential-privacy": "Differential privacy formalizes anonymity by requiring that the presence or absence of any single record in a dataset barely changes the probability of any output. This is achieved by adding calibrated noise, often through the Laplace or Gaussian mechanism, with a privacy budget epsilon controlling the trade-off between noise and accuracy. The Apple and US Census deployments are notable examples. Composition theorems track how privacy degrades as many queries are answered.",
    "surface-code-quantum-error-correction": "The surface code is a topological quantum error-coding scheme that encodes one logical qubit in a 2D lattice of physical qubits with nearest-neighbour parity checks. It tolerates a physical error rate near one percent, the highest threshold of practical codes, making it a leading candidate for fault-tolerant quantum computing. Logical operations are performed through braiding anyons, and it requires only local measurements, which suits superconducting chip layouts.",
    "vector-clocks-causality": "Vector clocks capture causal ordering in distributed systems without a global clock. Each process maintains a counter array, incrementing its own entry on every event and merging by taking the element-wise maximum when messages arrive. Two events are concurrent if neither clock dominates the other, unlike scalar timestamps which falsely order them. Vector clocks detect causality violations and are used in Dynamo-style databases and conflict detection for replicated data.",
}


def main() -> None:
    for folder, docs in ((ROOT / "data/docs", GENERAL_DOCS), (ROOT / "data/research", RESEARCH_DOCS)):
        folder.mkdir(parents=True, exist_ok=True)
        for name, text in docs.items():
            (folder / f"{name}.txt").write_text(text, encoding="utf-8")
        print(f"Wrote {len(docs)} files to {folder.relative_to(ROOT)}")


if __name__ == "__main__":
    main()
